insert into public.creators (id, handle, display_name, studio_name, headline, bio, location, timezone, avatar_seed, accent, avatar_kind, availability, verified_at, member_since, philosophy, day_rate_inr, minimum_engagement_inr, turnaround_days, rating, review_count, badges) values
  ('cr-aarav', 'aarav.mehta', 'Aarav Mehta', 'Frame Latitude', 'Cinematic film for brands that refuse the stock look', 'I make films that were never shot. Ten years of camera and previz experience, redirected into a pipeline where the shot list is the source of truth and the pixels are the last step. Most of my work is 30–60 seconds and has to survive a sound-off feed at full brightness.', 'Mumbai, India', 'IST (UTC+5:30)', 'aarav-mehta-77', '#e0a15c', 'portrait', 'open', '2025-11-04', '2024-06', 'The camera is the hardest part and the model is the easiest. So I treat the model as a film printer: it is only allowed to do what the shot list already decided.', 145000, 320000, 12, 4.9, 38, ARRAY['Top 1% cinematic', 'Verified workflow', 'Frame.io partner']),
  ('cr-ishita', 'ishita.still', 'Ishita Rao', null, 'Synthetic photography for beauty and skin', 'Beauty imagery where the product is the hero and the model is plausible. I spent six years in stills retouching, which is exactly the skill set that synthetic photography needs and almost nobody has.', 'Bengaluru, India', 'IST (UTC+5:30)', 'ishita-rao-19', '#f0b7a0', 'portrait', 'limited', '2025-08-21', '2024-09', 'The job is not to make a face up. The job is to make a face nobody can find a reason to doubt — which is a much harder and more useful thing.', 96000, 180000, 7, 4.9, 51, ARRAY['Beauty category leader', 'Likeness-safe', 'Same-day turnaround']),
  ('cr-kabir', 'kabir.anand', 'Kabir Anand', 'Anand & Sons CG', 'Product renders with zero geometric drift', 'CAD-accurate product imagery. I generate the world around the product, never the product itself. If the silhouette, the seam, or the logo position moves by a millimetre, it does not ship.', 'Gurugram, India', 'IST (UTC+5:30)', 'kabir-anand-04', '#8fa6d8', 'abstract', 'open', '2026-01-15', '2025-02', 'Generation is good at weather, bad at engineering. I use it for the first and refuse it for the second.', 120000, 240000, 9, 4.8, 29, ARRAY['CAD-verified geometry', 'E-commerce specialist']),
  ('cr-tara', 'tara.motion', 'Tara Menon', null, 'Motion systems that stay on-brand at 40 assets', 'A motion grammar is a design system that moves. I build the rules once — easing, weight, transitions, sound cues — then every asset in the campaign inherits them for free.', 'Bengaluru, India', 'IST (UTC+5:30)', 'tara-menon-58', '#c79bf0', 'portrait', 'open', '2025-12-19', '2024-11', 'Brands do not need another beautiful video. They need the eleventh video to look like the first one.', 88000, 150000, 6, 4.9, 58, ARRAY['Highest approval rate', 'Systems thinker']),
  ('cr-rehan', 'rehan.synth', 'Rehan Qureshi', 'Second Room Audio', 'Music, voice and sound design for picture', 'I compose to picture, then clear it properly. Every stem is separated, fingerprinted and licensed in writing before it reaches a client, because the single most expensive mistake in this business is shipping a track that already belongs to someone.', 'Hyderabad, India', 'IST (UTC+5:30)', 'rehan-qureshi-33', '#7fd6c4', 'mark', 'booked', '2025-10-08', '2024-08', 'Audio is the only part of a campaign nobody notices when it is right and everybody notices when it is wrong.', 74000, 120000, 5, 4.8, 41, ARRAY['Rights-cleared audio', '9 languages']),
  ('cr-diya', 'diya.skin', 'Diya Chatterjee', null, 'Fabric, skin and texture — the parts that give it away', 'I work at the resolution where synthetic work fails: hairline against skin, weave against drape, clasp against finger. Twelve years of fashion still-life retouching, spent on the exact problem everyone else is hiding from.', 'Kolkata, India', 'IST (UTC+5:30)', 'diya-chatterjee-91', '#e59aa8', 'portrait', 'open', '2026-02-11', '2025-03', 'Nobody can name the exact thing that looks wrong. I can, and I have made a career of removing it.', 110000, 200000, 8, 4.9, 22, ARRAY['Texture specialist', 'Luxury approved']),
  ('cr-nikhil', 'nikhil.previz', 'Nikhil Varma', 'Greybox', 'Real-time previz that becomes the final shot', 'For games and VFX. I capture camera paths from your own level, lock the look in-engine, then up-res them into final-quality shots that conform back with matching cameras. Nothing is invented that a designer would not have approved.', 'Hyderabad, India', 'IST (UTC+5:30)', 'nikhil-varma-64', '#8fd0f5', 'abstract', 'limited', '2025-09-27', '2024-10', 'If the shot was not playable, it was never a design idea. Previz that cannot be shipped is a mood board with extra steps.', 135000, 300000, 14, 4.8, 18, ARRAY['Engine-native', 'TAA stable']),
  ('cr-ananya', 'ananya.char', 'Ananya Iyer', 'Twelve Poses', 'Character systems that survive contact with a story', 'A character bible is only worth something if the character is still the same character in shot forty. I fine-tune an identity embedding per project and validate it against prompts the client never sees.', 'Chennai, India', 'IST (UTC+5:30)', 'ananya-iyer-27', '#f2c46b', 'portrait', 'open', '2026-03-02', '2025-04', 'Consistency is a rig, not a prompt. I build the rig, then I let the prompts do what prompts are good at.', 92000, 175000, 11, 4.7, 26, ARRAY['Consistency specialist', 'Story-first']),
  ('cr-rohan', 'rohan.perf', 'Rohan D''Souza', null, 'Performance creative at volume, measured properly', 'One concept, six hooks, every placement. I work from your account''s last ninety days rather than from taste, and I kill my own winners when the CTR says so.', 'Mumbai, India', 'IST (UTC+5:30)', 'rohan-dsouza-45', '#f08b6a', 'abstract', 'open', '2025-07-30', '2024-07', 'A concept is a hypothesis. If it does not move the number, it was never a concept, it was a preference.', 82000, 140000, 4, 4.9, 71, ARRAY['88 engagements', '4-day turnaround', 'Highest repeat rate']),
  ('cr-meera', 'meera.food', 'Meera Joshi', 'Steam & Salt', 'Food that looks like it was eaten from', 'Food imagery fails in the steam, the crumbs, the imperfection. I shoot nothing and generate everything, but I grade against real reference sets until the difference is invisible at arm''s length.', 'Pune, India', 'IST (UTC+5:30)', 'meera-joshi-12', '#e8b45c', 'portrait', 'limited', '2025-11-28', '2024-09', 'Appetite is a lighting problem before it is a plating problem.', 70000, 125000, 5, 4.8, 44, ARRAY['Food category leader', 'Package-aware']),
  ('cr-yuki', 'yuki.frames', 'Yuki Tanaka', null, '2D motion and illustration with a printed-paper brain', 'I came to generative work from ten years of print illustration. That is why my images hold line weight and negative space the way a screen-printed poster does, even when every pixel was made by a sampler.', 'Bengaluru, India', 'IST (UTC+5:30)', 'yuki-tanaka-83', '#9fd8f0', 'portrait', 'booked', '2026-01-08', '2025-05', 'A sampler will give you average of everything. Restraint is the only way to get a specific thing.', 78000, 140000, 7, 4.7, 24, ARRAY['Print-trained', 'Style-locked']),
  ('cr-samar', 'samar.occasion', 'Samar Fatima', null, 'Luxury occasion work, handled carefully', 'Weddings, milestone celebrations and heritage campaigns. The clients are real people with real dates, so my pipeline is built around approvals that arrive on time and imagery that nobody at the venue recognises as synthetic.', 'Lucknow → Mumbai', 'IST (UTC+5:30)', 'samar-fatima-36', '#e6b7c9', 'portrait', 'open', '2025-09-03', '2025-01', 'Real families, real deadlines. The synthetic part is invisible and that is the entire job.', 64000, 110000, 6, 4.9, 39, ARRAY['Milestone specialist', 'Same-week delivery']),
  ('cr-vikram', 'vikram.data', 'Vikram Sethi', 'Adviser Studio', 'Fintech creative where every claim is defensible', 'Regulated creative has one extra rule: the image may not imply a return. I build the visual and run every on-frame claim through the client''s substantiation file before it renders. Nothing goes live with a number I cannot source.', 'Bengaluru, India', 'IST (UTC+5:30)', 'vikram-sethi-61', '#7fb0e8', 'abstract', 'open', '2026-04-18', '2025-06', 'In fintech, a beautiful frame with an unsourced claim is not creative. It is a notice period.', 105000, 220000, 10, 4.6, 20, ARRAY['Regulated-category clearance', 'Claims audit included']),
  ('cr-priya', 'priya.well', 'Priya Nandakumar', null, 'Wellness imagery that does not edit people into oblivion', 'No body reshaping, no skin lightening past the real tone, no six-pack that was not there. I generate warm, believable images and then run the same retouching standard I would apply to a real photographer''s work.', 'Bengaluru, India', 'IST (UTC+5:30)', 'priya-nandakumar-07', '#9ed6a8', 'portrait', 'open', '2025-12-01', '2025-02', 'If the subject would be uncomfortable seeing the before and after, we do not retouch it that way.', 68000, 120000, 6, 4.8, 37, ARRAY['Body-positive policy', 'Regulated-clean'])
