insert into public.workflows (id, name, summary, duration_hours, verified, last_run_at) values
  ('wf-cinematic-previs', 'Cinematic pre-vis to grade', 'Shotlist first, then 6-frame previz in a 3D blockout, then generation against the previz so continuity is structural rather than lucky.', 26, true, '2026-08-14'),
  ('wf-photoreal-set', 'Synthetic photoreal set', 'One reference subject, a physically-plausible lighting rig, then 60–120 candidates ranked on anatomy, texture and brand-safe framing.', 14, true, '2026-09-02'),
  ('wf-product-render', 'Product render & retouch pipeline', 'CAD-accurate geometry, physically-based materials, then AI-assisted set dressing that never changes the product silhouette.', 18, true, '2026-08-28'),
  ('wf-motion-system', 'Motion system & kinetic type', 'A brand-consistent motion grammar defined as a system, then templates generated for every asset in the campaign.', 12, true, '2026-09-11'),
  ('wf-character-bible', 'Character bible & consistency', 'A locked character sheet that survives across shots, films and games, with a trained identity embedding.', 30, true, '2026-07-30'),
  ('wf-audio-stack', 'Music, mix & voice stack', 'Composition generated to picture, then stems cleared and the voice directed and conformed against the mix.', 10, true, '2026-09-18'),
  ('wf-fabric-realism', 'Fabric, skin & texture realism', 'The hardest problem in synthetic imagery, solved with a material library, a reference-lit pass and per-region artifact rejection.', 22, true, '2026-08-05'),
  ('wf-previs-game', 'Real-time previz for games & VFX', 'Sequences previzzed in-engine from the client''s grey-box level, then up-resolved into final-quality shots.', 16, true, '2026-09-05'),
  ('wf-performance-creative', 'Performance creative at volume', 'One concept, systematically deconstructed into channel-native variants with a measured winner, not a coin flip.', 8, true, '2026-09-22'),
  ('wf-luxury-campaign', 'Luxury campaign & heritage', 'Craft-forward imagery with extreme restraint, sourced references cleared through the client''s heritage archive.', 26, true, '2026-06-19'),
  ('wf-sound-design-gen', 'Generative sound design', 'Foley and ambience generated, then re-recorded where a real-world layer is required for believability.', 7, true, '2026-08-20'),
  ('wf-wellness-editorial', 'Wellness editorial & retouch', 'Warm, believable imagery with body-positive retouching that never invents anatomy.', 9, true, '2026-09-15')
insert into public.workflow_stages (workflow_id, slug, position, name, description, human_checkpoint, weight) values
  ('wf-cinematic-previs', 's1', 0, 'Shot architecture', 'Lock the narrative beats, lens list and eyelines before a single frame is generated.', 'Director selects the emotional beat curve and rejects any shot that does not advance it.', 10),
  ('wf-cinematic-previs', 's2', 1, '3D blockout previz', 'Grey-box the camera path and subject blocking in Unreal so generated shots inherit real parallax.', 'Blocking review — camera height and eyeline locked against the brand''s shot grammar.', 18),
  ('wf-cinematic-previs', 's3', 2, 'Keyframe generation', 'Two reference frames per shot from FLUX and Imagen, comped against the blockout geometry.', 'Select the frame that carries the intended performance, not the most flattering one.', 24),
  ('wf-cinematic-previs', 's4', 3, 'Motion synthesis', 'Image-to-video on the approved keyframes, multiple seeds per shot, ranked by optical-flow stability.', 'Hands, cloth and secondary motion are rejected automatically; humans re-roll and re-grade.', 28),
  ('wf-cinematic-previs', 's5', 4, 'Comp & grade', 'Nuke comp for continuity, Resolve grade against the campaign LUT, skin-tone pass per talent proxy.', 'Final QC against the client''s brand black, contrast and skin-tone policy.', 20),
  ('wf-photoreal-set', 's1', 0, 'Subject identity lock', 'Build a 12-pose identity sheet for the synthetic subject; every frame is generated against that sheet.', 'Identity sign-off — the sheet becomes the contractual reference for likeness consistency.', 16),
  ('wf-photoreal-set', 's2', 1, 'Lighting rig design', 'Describe the rig as a physical setup so the model resolves consistent falloff and shadow density.', 'Lighting direction confirmed against the moodboard, not against a style keyword.', 14),
  ('wf-photoreal-set', 's3', 2, 'Candidate sweep', '120+ candidates across set, wardrobe and pose variations, scored on anatomy and texture artefacts.', 'Automatic artefact rejection, then human ranking of the top 20.', 34),
  ('wf-photoreal-set', 's4', 3, 'Retouch & grade', 'Frequency-separated cleanup, fabric texture recovery, brand grade and final crop set.', 'Ensure no identifiable real person is present — right-of-publicity check on every face.', 26),
  ('wf-photoreal-set', 's5', 4, 'Manifest & license stamp', 'C2PA manifest written, SynthID embedded, dual-branded burn-in applied before the client ever sees it.', 'Provenance review before release from the sandbox.', 10),
  ('wf-product-render', 's1', 0, 'Geometry & CAD import', 'Import the client''s CAD or rebuild from spec sheets at millimetre tolerance.', 'Dimensional check against the client''s physical sample.', 20),
  ('wf-product-render', 's2', 1, 'Material authoring', 'Anisotropic metals, dielectric clearcoats, fabric sheen — authored as real shaders, not prompted.', 'Material approval from the client''s product team.', 22),
  ('wf-product-render', 's3', 2, 'Set generation', 'Environment generated around the locked geometry; the product mask is never re-synthesised.', 'Reject any environment that reads as a competitor''s brand language.', 26),
  ('wf-product-render', 's4', 3, 'Light & composite', 'Product lighting authored in-engine; the generated plate is graded to match exactly.', 'Specular and shadow-density match check against a physical shoot.', 22),
  ('wf-product-render', 's5', 4, 'Format variants', 'Master render, then crop-derived variants for every requested aspect ratio without re-generation.', 'Safe-area verification per channel.', 10),
  ('wf-motion-system', 's1', 0, 'Motion grammar', 'Define easing, weight and transition rules once, from the brand''s existing identity motion.', 'Brand team signs the motion grammar before any asset is built.', 20),
  ('wf-motion-system', 's2', 1, 'Kinetic type build', 'Type animation authored in After Effects; AI is used for texture and background only.', 'Legibility pass at every duration and safe-area.', 28),
  ('wf-motion-system', 's3', 2, 'Generated texture layer', 'Loops, gradients and noise beds generated to match the palette, then conformed to the type animation.', 'Loop-point and loop-seam validation.', 22),
  ('wf-motion-system', 's4', 3, 'Master & cutdowns', 'One master, then algorithmic cutdowns to every ratio and duration in the brief.', 'Narrative integrity check on each cutdown — a cutdown must still make sense alone.', 30),
  ('wf-character-bible', 's1', 0, 'Design brief & silhouette', 'Three silhouette directions first — a silhouette that does not read is dead on arrival.', 'Client picks a silhouette before any detail is drawn.', 18),
  ('wf-character-bible', 's2', 1, 'Identity embedding', 'Fine-tune a checkpoint on the approved sheet and validate it across 40 unseen prompts.', 'Fail-case review — prompts where the character drifts are re-balanced.', 30),
  ('wf-character-bible', 's3', 2, 'Turnaround & expression set', 'Turnaround, expression grid and wardrobe set generated once and reused as the canonical reference.', 'Wardrobe and prop continuity locked with the narrative team.', 22),
  ('wf-character-bible', 's4', 3, 'Sequence production', 'Shot sequences generated against the embedding with per-shot seeds pinned for reproducibility.', 'Continuity board review before animation begins.', 30),
  ('wf-audio-stack', 's1', 0, 'Brief-to-composition', 'BPM, key and instrumentation derived from the cut''s emotional arc, then composed to picture.', 'Composer/arranger reworks anything that reads as a stock template.', 34),
  ('wf-audio-stack', 's2', 1, 'Stem clearance', 'Stems separated and checked against the platform''s audio fingerprint service before licensing.', 'Manual clearance confirmation — automated checks are advisory only.', 18),
  ('wf-audio-stack', 's3', 2, 'Voice direction & conform', 'Synthetic VO directed take-by-take, then conformed to the picture with proper room tone.', 'Director-approved read for emotion, pace and regional pronunciation.', 30),
  ('wf-audio-stack', 's4', 3, 'Mix & loudness', 'Broadcast/streaming loudness normalisation and a delivery spec sheet per platform.', 'Final listen on the client''s actual playback environment.', 18),
  ('wf-fabric-realism', 's1', 0, 'Material library', 'Curated reference swatches per fabric and skin profile, tagged with lighting response.', 'Photographer sign-off on the library — the client trusts this more than the model does.', 22),
  ('wf-fabric-realism', 's2', 1, 'Reference-lit generation', 'Generation is conditioned on a photographed light rig rather than a lighting keyword.', 'Highlight rolloff and shadow colour checked on a calibrated display.', 30),
  ('wf-fabric-realism', 's3', 2, 'Region artifact pass', 'Hands, jewellery clasp, fabric weave and fabric-to-skin contact are inspected per region at 200%.', 'Human rejection on every region — this stage has no automatic pass.', 30),
  ('wf-fabric-realism', 's4', 3, 'Skin-tone integrity', 'Undertone is preserved end-to-end; no global beautify pass is applied after generation.', 'Talent-proxy approval of the final undertone against the identity sheet.', 18),
  ('wf-previs-game', 's1', 0, 'Engine capture', 'Camera paths captured from the client''s own level so every shot is playable, not just pretty.', 'Gameplay readability review with the design team.', 24),
  ('wf-previs-game', 's2', 1, 'Look target', 'Target frames produced in-engine as the look contract for the up-res pass.', 'Art director sign-off on the look target before up-res.', 18),
  ('wf-previs-game', 's3', 2, 'Up-res & generate', 'Deferred passes re-rendered at delivery resolution, then generative detail layers added on top.', 'TAA and temporal stability verified — generation must not introduce flicker.', 38),
  ('wf-previs-game', 's4', 3, 'Plate conform', 'Shots conformed back into the engine with matching cameras and timecodes.', 'Camera-match validation against the capture data.', 20),
  ('wf-performance-creative', 's1', 0, 'Concept + hook matrix', 'One concept, six hooks, mapped to the placements that historically respond to each.', 'Performance lead signs the hook matrix against last 90 days of account data.', 22),
  ('wf-performance-creative', 's2', 1, 'Variant production', 'Static and motion variants generated per hook at native placement resolution.', 'Brand-safety sweep for regulated categories.', 40),
  ('wf-performance-creative', 's3', 2, 'Copy & on-screen', 'Overlay copy generated per placement, then human-edited to remove hallucinated claims.', 'Every claim is checked against the client''s substantiation file. Non-negotiable.', 20),
  ('wf-performance-creative', 's4', 3, 'Winner iteration', 'The winning hook gets two further generations before the batch is released.', 'Kill decision made on measured CTR, not on taste.', 18),
  ('wf-luxury-campaign', 's1', 0, 'Archive research', 'Study the house archive — poses, lighting ratios, negative space ratios — before generating anything.', 'Heritage team signs the reference board. No reference leaves the archive.', 14),
  ('wf-luxury-campaign', 's2', 1, 'Restrained generation', 'Low-variance generation; the model is constrained so it cannot embellish.', 'Anything the model ''improved'' on is reverted. Restraint is the brief.', 34),
  ('wf-luxury-campaign', 's3', 2, 'Craft detail pass', 'Engraving, stitching, stone clarity and foil detail resolved at high magnification.', 'Craft director reviews every product-critical detail at 200%.', 28),
  ('wf-luxury-campaign', 's4', 3, 'Typographic restraint', 'Lockup and copy set with generous negative space per the house style guide.', 'Final sign-off is with the house, not the agency.', 24),
  ('wf-sound-design-gen', 's1', 0, 'Texture design', 'Ambience beds generated to the cut''s geography and time of day.', 'Producer confirms the bed does not fight the VO.', 28),
  ('wf-sound-design-gen', 's2', 1, 'Foley pass', 'Generated foley first; anything implausible is recorded in a real foley stage.', 'Engineer flags every implausible layer for live recording.', 34),
  ('wf-sound-design-gen', 's3', 2, 'Mix & deliver', 'Broadcast-spec mix with stems and a delivery note for the client''s broadcaster.', 'Loudness and true-peak verified against the platform spec.', 38),
  ('wf-wellness-editorial', 's1', 0, 'Tone & light', 'Establish a natural-light reference so the set never reads clinical.', 'Art director locks the light temperature before any subject is generated.', 20),
  ('wf-wellness-editorial', 's2', 1, 'Subject generation', 'Generate against the client''s existing talent identity sheet where photography is paired.', 'No body reshaping. Retouching removes artefacts; it does not idealise.', 38),
  ('wf-wellness-editorial', 's3', 2, 'Grade & skin', 'Consistent warmth across the set with per-skin-tone calibrated passes.', 'Skin-tone calibration check by eye under D65 reference.', 24),
  ('wf-wellness-editorial', 's4', 3, 'Claims audit', 'Every on-frame claim, ingredient callout and numeric assertion is checked against the client''s approved list.', 'Regulatory copy sign-off. This stage has never been automated.', 18)
