insert into public.brief_sessions (slug, brief_id, brand_id, status, draft, created_at, updated_at) values
  ('bs-monsoon', 'br-monsoon', 'bd-nirvani', 'submitted', '{}'::jsonb, '2026-09-02T10:14:00Z', '2026-09-02T10:26:00Z'),
