insert into public.conversation_turns (slug, session_id, role, text, at, extracted_fields, simulated) values
  ('t1', 'bs-monsoon', 'assistant', 'Let''s start with what already exists. What did the FY25 monsoon campaign look like, and what worked about it?', '2026-09-02T10:14:02Z', ARRAY[]::text[], false),
  ('t2', 'bs-monsoon', 'brand', 'We shot it in Camera B with a long lens. The grade was flat and warm, which is why it worked. Everyone else was doing blue rain and it looked like a detergent ad.', '2026-09-02T10:15:10Z', ARRAY['referenceNotes'], false),
  ('t3', 'bs-monsoon', 'assistant', 'Noted — warm, flat, long lens. Is the camera going to a real set, or should the creator build it?', '2026-09-02T10:15:30Z', ARRAY[]::text[], false),
  ('t4', 'bs-monsoon', 'brand', 'It should not look like a set. We have eleven saris and four models and three days of everyone''s availability, and rain scheduling in September is a joke.', '2026-09-02T10:16:20Z', ARRAY['rawIdea'], false),
  ('t5', 'bs-monsoon', 'assistant', 'Understood. That means the weather is created, not captured. Three questions left: where does it run, for how long may the film be used commercially, and how long can we take?', '2026-09-02T10:16:48Z', ARRAY[]::text[], false),
  ('t6', 'bs-monsoon', 'brand', 'India only, three years. Paid social, the site, print in the two December issues, and it plays at the store launch in Delhi. Four weeks end to end, and we need to see something in week one or the stylists will go elsewhere.', '2026-09-02T10:18:05Z', ARRAY['commercialUse', 'budget', 'timeline'], false),
  ('t7', 'bs-monsoon', 'assistant', 'I have enough. Drafting the structured brief now — you will get a version you can edit field by field before anything is published.', '2026-09-02T10:19:11Z', ARRAY[]::text[], false),
  ('t1', 'bs-ignition', 'brand', 'something monsoon-ish, we shoot in the rain usually but its too slow to schedule everyone', '2026-09-15T08:02:01Z', ARRAY[]::text[], false),
  ('t2', 'bs-ignition', 'assistant', 'I can help with that. Who is the audience, and what should they feel in the first three seconds?', '2026-09-15T08:02:30Z', ARRAY[]::text[], false),
  ('t3', 'bs-ignition', 'brand', 'launch film for the new ev, short, punchy, mostly vertical, we need it next week', '2026-09-15T08:03:10Z', ARRAY[]::text[], false),
  ('t4', 'bs-ignition', 'assistant', 'A week is tight but workable if the vehicle geometry comes from CAD rather than from a camera. Do you have the CAD, and is there a claim that has to appear on screen?', '2026-09-15T08:03:44Z', ARRAY[]::text[], false),
  ('t5', 'bs-ignition', 'brand', 'yes we have cad. range is 412 certified so that can go on screen. worldwide, 2 years, everything.', '2026-09-15T08:06:02Z', ARRAY['commercialUse', 'referenceNotes'], false),
  ('t1', 'bs-undertone', 'brand', 'we need the serum shot on six different skin tones, no tokenism', '2026-09-11T13:37:02Z', ARRAY[]::text[], false),
  ('t2', 'bs-undertone', 'assistant', 'Six tones is a strong constraint. Should lighting and background be held identical across all six so undertone is the only variable?', '2026-09-11T13:37:40Z', ARRAY[]::text[], false),
  ('t3', 'bs-undertone', 'brand', 'yes. and the bottle must not change between shots. we got burned by an agency last year that regenerated the cap.', '2026-09-11T13:38:55Z', ARRAY['referenceNotes', 'excludedStyles'], false),
  ('t4', 'bs-undertone', 'assistant', 'That is a packaging-locked render requirement, not a retouching preference — it changes which kind of creator you need. Anything we must never do to skin?', '2026-09-11T13:39:30Z', ARRAY[]::text[], false),
  ('t5', 'bs-undertone', 'brand', 'no global lightening. ever. we will reject the set.', '2026-09-11T13:41:10Z', ARRAY['excludedStyles'], false)
insert into public.briefs (slug, code, title, brand_id, campaign_objective, raw_idea, refined_summary, audience, tone, style_tags, reference_notes, excluded_styles, must_have_signals, status, session_id, embedding_note, created_at, updated_at) values
  ('br-monsoon', 'BRF-2026-0141', 'Monsoon Reveal — Autumn/Winter 2026', 'bd-nirvani', 'Open the AW26 collection with a monsoon film that makes handwoven sari feel like weather, not garment. Sell to an existing customer base and to press.', 'something monsoon-ish, we shoot in the rain usually but its too slow to schedule everyone, want it to feel like the first rain of the season', 'A 50–60 second hero film plus vertical cutdowns, opening on the first monsoon shower over stone. Handwoven sari is the subject; the model is present but secondary. The emotional target is relief, not glamour — the moment the season turns.', 'Women 26–40, urban and tier-2, already buying occasion wear. Secondary: fashion press and stylists who set the AW narrative.', ARRAY['quiet-luxury', 'warm', 'aspirational'], ARRAY['cinematic', 'analog film', '70s grain', 'botanical organic'], ARRAY['Shot the FY25 monsoon campaign in Camera B — grade matches better than any LUT we own.', 'No visible logos other than the house mark in the end card.', 'Weather must feel real: wet stone specular, moving fabric, no rain-on-glass cliché.'], ARRAY['high-gloss beauty lighting', 'neon', 'over-saturated colour', 'stock-smile casting'], ARRAY['identity', 'tools', 'workflow', 'portfolio'], 'in-negotiation', 'bs-monsoon', 'Cinematic monsoon sari hero film, quiet luxury, analog grain, stone and water, 55s anamorphic, vertical cutdowns, India 36 months paid social and print.', '2026-09-02T10:14:00Z', '2026-09-19T07:41:00Z'),
  ('br-ignition', 'BRF-2026-0163', 'Ignition — EV launch film', 'bd-vayu', 'Launch film for the Ignition platform. Must survive a sound-off autoplay on a phone before it survives a cinema.', 'launch film for the new ev, short, punchy, mostly vertical, we need it next week', 'A 30 second launch film cut vertical-first. The product must be geometrically exact; the world around it can be generous. One clear idea, no narration, no claims on screen.', 'Urban male 28–45, current ICE owner considering an EV, high-intent.', ARRAY['confident', 'urgent', 'clinical'], ARRAY['industrial', 'clinical minimal', 'chromatic'], ARRAY['CAD files for the Ignition body will be supplied — nothing about the vehicle silhouette may be generated.', 'One claim on screen: the certified range figure, taken from the homologation certificate.'], ARRAY['handheld shakiness', 'lens flare', 'people''s faces as hero'], ARRAY['identity', 'tools', 'portfolio', 'delivery'], 'open', 'bs-ignition', 'EV launch film vertical-first, CAD-accurate vehicle, industrial clinical, one homologated range claim, worldwide 24 months paid and retail.', '2026-09-15T08:02:00Z', '2026-09-15T08:02:00Z'),
  ('br-undertone', 'BRF-2026-0158', 'Undertone — Serum launch stills', 'bd-halcyon', 'Launch stills for a serum positioned entirely on undertone accuracy across six skin tones.', 'we need the serum shot on six different skin tones, no tokenism, and the bottle must not change between shots', 'Six stills, one product, six calibrated skin tones. Lighting, background and framing held constant so the undertone is the only variable a viewer can perceive.', 'Women 22–38, ingredient-led buyers who already read the INCI list.', ARRAY['reassuring', 'clinical', 'quiet-luxury'], ARRAY['clinical minimal', 'hyperreal', 'monochrome'], ARRAY['Same bottle render across all six. We will reject any set where the packaging differs.', 'No global skin lightening. Undertone must match the identity sheet per subject.'], ARRAY['airbrushing', 'porcelain retouch', 'colour temperature drift between frames'], ARRAY['identity', 'portfolio', 'client'], 'shortlisted', 'bs-undertone', 'Serum launch stills, six calibrated skin tones, constant lighting, packaging locked, no skin lightening, worldwide 36 months paid and packaging.', '2026-09-11T13:37:00Z', '2026-09-16T09:20:00Z')
insert into public.brief_deliverables (brief_id, content_type, aspect_ratio, quantity, duration_seconds, notes, position) values
  ('br-monsoon', 'cinematic-video', '21:9', 1, 55, 'Hero film. Master plus ProRes 4444 and H.264 review.', 0),
