insert into public.offers (slug, code, brief_id, creator_id, brand_id, amount_inr, delivery_days, revisions_included, concept_rounds, exclusivity, status, translated_brief, note, created_at, responded_at) values
  ('of-aarav-monsoon', 'OFR-2026-0442', 'br-monsoon', 'cr-aarav', 'bd-nirvani', 465000, 24, 2, 2, 'exclusive-category', 'accepted', 'You asked for a film that opens on the first monsoon shower over stone, in a flat warm grade on a long lens, with the sari as the subject and the model present but secondary. Fifty-five seconds, 21:9. The rain is not scheduled — it is created, so no one''s availability is at risk.
