insert into public.contract_clauses (slug, contract_id, heading, body, requires_explicit_acknowledgement, position) values
  ('c-parties', 'ct-monsoon-start', 'Parties and identity', 'Nirvani Atelier LLP, identity asserted through DigiLocker as GSTIN 27AAGCN••••, and Frame Latitude, operated by Aarav Mehta, identity asserted through DigiLocker at AAL2. CREAM holds the assertions only. Neither party has produced a government identity document to CREAM at any point.', false, 0),
  ('c-watermark', 'ct-monsoon-start', 'Pre-release watermarking', 'Every sample released before final approval carries a visible dual-branded burn-in (CREAM and the creator) and an imperceptible watermark envelope. The brand may not remove, crop past, or obscure either mark. Sample assets are licensed for review only and carry no distribution right.', true, 1),
  ('c-scope', 'ct-monsoon-start', 'Scope and change control', 'Deliverables, formats, revisions and concept rounds are fixed by the attached brief. A change to any of these requires a written scope amendment countersigned by both parties and, where the change increases cost, a supplementary escrow release.', true, 2),
  ('c-reject', 'ct-monsoon-start', 'Rejection grounds', 'A brief may be rejected only where the final output materially departs from a sample the brand approved in writing during the agreed sample round. Aesthetic preference alone is not a rejection ground. Where a claim of departure is upheld, remedy is partial or full refund as determined jointly by CREAM''s review specialist and the parties.', true, 3),
  ('c-rights', 'ct-monsoon-start', 'Rights granted', 'On final approval and settlement of the engagement close agreement, the brand receives the licence described in the brief''s commercial-use terms, for the stated territory, duration, channels and media. No right not expressly granted is granted, including resale, sublicensing and use as a model-training input.', true, 4),
  ('c-escrow', 'ct-monsoon-start', 'Escrow and settlement', '₹4,65,000 has been authorised with Razorpay and held by CREAM''s sub-account. Funds release against the four milestones in the offer. Settlement is net-15 from milestone acceptance. A dispute freezes the disputed tranche only.', true, 5),
  ('c-nda', 'ct-monsoon-nda', 'Mutual confidentiality', 'The unreleased campaign, the sari reference photography, and the brand''s AW26 assortment are confidential until the agreed announcement date. Either party may disclose to a professional adviser under equivalent duty.', true, 0)
