  ('pv-monsoon-r1', 'en-aarav-1', 'gn-monsoon-1', 'monsoon-hero-samples-v1', '{"version":"1.3","claimGenerator":"CREAM Provenance Stamper 2.1","certificateIssuer":"CREAM Content Credentials (demo CA)","assertions":["c2pa.created — Frame Latitude, 2026-09-11T09:22Z","c2pa.contentAuthenticity — AI-generated, declared","cream.assertion.humanCheckpoints — 3 stages with named human decision points","cream.assertion.toolChain — Veo 3, Kling 2.0, Gen-4, FLUX 1.1 Pro, Nuke 16, Resolve 20","cream.assertion.brandTerms — Nirvani Atelier AW26, contract CTR-2026-0912"],"manifestHash":"sha256:9e21b7c40d8a6f5312c0b7e94d2a6f8013bc5d47e209a6b1c843d7e05f219a6b","signedAt":"2026-09-11T09:22:41Z"}'::jsonb, '{"provider":"mock-synthid","embedded":true,"strength":0.6,"payloadId":"syid_7f2a91c4e08b","extractable":true,"lastDetection":{"matched":true,"confidence":0.97,"at":"2026-09-11T09:23:02Z"}}'::jsonb, '{"platformWatermark":"CREAM","creatorWatermark":"Aarav Mehta · Frame Latitude","position":"centre-tile","opacity":0.82}'::jsonb, ARRAY['{"at":"2026-09-11T09:22:41Z","event":"Generated","actor":"Frame Latitude pipeline"}'::jsonb, '{"at":"2026-09-11T09:22:52Z","event":"Human checkpoint signed","actor":"Aarav Mehta"}'::jsonb, '{"at":"2026-09-11T09:23:02Z","event":"Watermark embedded and verified","actor":"CREAM Provenance"}'::jsonb, '{"at":"2026-09-11T09:24:10Z","event":"Released to brand sandbox","actor":"CREAM"}'::jsonb])
insert into public.reviews (slug, creator_id, brand_name, rating, body, at, engagement_code, verified) values
  ('rv-1', 'cr-aarav', 'Nirvani Atelier', 5, 'We had been burned twice by agencies who promised a rain shoot and delivered a blue filter. Aarav blocked the camera before anything was generated, and the result held up on a cinema screen, which none of ours had.', '2026-08-14', 'ENG-2025-0244', true),
  ('rv-2', 'cr-aarav', 'Vayu Motors', 5, 'Handed over CAD on day one, got a launch film on day nine. The vehicle never moved by a millimetre, which was the only thing we actually cared about.', '2026-06-02', 'ENG-2026-0121', true),
  ('rv-3', 'cr-ishita', 'Halcyon', 5, 'Six undertones, one lighting rig, zero bottle drift. She rejected more of her own work than we would have. That is why we came back.', '2026-09-16', 'ENG-2026-0302', true),
  ('rv-4', 'cr-diya', 'Mehra Jewellers', 5, 'The clasp detail at 200% is the only reason this brief is worth discussing. Nobody else sends work that survives being looked at properly.', '2026-07-22', 'ENG-2026-0187', true),
  ('rv-5', 'cr-tara', 'Chai Republic', 5, 'She built a motion grammar in week one and then produced forty assets in week two that all looked related. Our brand team has stopped reviewing assets individually.', '2026-08-30', 'ENG-2026-0266', true),
  ('rv-6', 'cr-rehan', 'Nova Studios', 4, 'Clearance paperwork is immaculate — I have never had to chase a rights document. One round took longer than quoted because of our own late script change, which was not on them.', '2026-05-19', 'ENG-2026-0093', true),
  ('rv-7', 'cr-rohan', 'Vayu Motors', 5, 'Sent a hook matrix, killed her own favourite on day four because the number said so. Refreshing to work with someone who will tell you the good idea is not working.', '2026-07-04', 'ENG-2026-0158', true),
  ('rv-8', 'cr-nikhil', 'Ironwood Interactive', 4, 'Camera paths came out of our own level and conformed back into the engine. Two sequences needed an extra up-res pass, but the design team approved everything we captured.', '2026-04-28', 'ENG-2026-0044', true),
  ('rv-9', 'cr-priya', 'Kettle & Co', 5, 'The first agency we spoke to offered to ''even out'' skin tones. Priya wrote that into her terms as a rejection condition before we had even asked.', '2026-08-08', 'ENG-2026-0240', true),
  ('rv-10', 'cr-ishita', 'Aurum Fragrances', 4, 'Turnaround slipped two days when we changed the bottle, but the change was ours and she flagged it before starting rather than after.', '2026-03-11', 'ENG-2026-0022', true),
  ('rv-11', 'cr-kabir', 'Voltedge', 5, 'Housing, ports, tolerances — identical to the CAD across 41 renders. Our engineering team checked, which never happens.', '2026-06-30', 'ENG-2026-0145', true),
  ('rv-12', 'cr-vikram', 'Meridian Capital', 4, 'Compliance wrote this brief to be uncreative. He made it uncreative and legible at the same time, which is genuinely hard.', '2026-08-21', 'ENG-2026-0273', true),
  ('rv-13', 'cr-yuki', 'Lumen Learning', 5, 'Fourteen frames, one line weight, one ink. It looks screen-printed and it is entirely synthesised. Nobody in the studio could say how.', '2026-05-30', 'ENG-2026-0110', true),
  ('rv-14', 'cr-samar', 'Private client', 5, 'Two hundred and forty guests, none of whom knew a single pixel was synthetic. Delivered nine hours before the reception.', '2026-07-07', 'ENG-2026-0132', true),
  ('rv-15', 'cr-ananya', 'Foxglove Animation', 4, 'The character survived forty shots. We tested it with prompts she had never seen, which is the only test that counts.', '2026-06-14', 'ENG-2026-0129', true),
  ('rv-16', 'cr-meera', 'Chai Republic', 5, 'The steam is the whole thing. Our food photographer asked who shot it and could not believe the answer.', '2026-08-25', 'ENG-2026-0259', true)
